<?php
require __DIR__.'/app/bootstrap.php';
require_once __DIR__.'/app/Core/Tenant.php';
Auth::require();Tenant::ensureSchema();Tenant::boot();Tenant::requirePermission('api.manage');
pdo()->exec("CREATE TABLE IF NOT EXISTS workspace_api_tokens (id INT AUTO_INCREMENT PRIMARY KEY,workspace_id INT NOT NULL,user_id INT NULL,name VARCHAR(120) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,token_prefix VARCHAR(32) NOT NULL,scopes VARCHAR(500) NOT NULL,expires_at DATETIME NULL,last_used_at DATETIME NULL,revoked_at DATETIME NULL,created_at DATETIME NULL,INDEX idx_wapi_workspace(workspace_id,revoked_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='create'){ $name=trim((string)($_POST['name']??''));if(!$name)throw new RuntimeException('نام توکن الزامی است.');$scopes=$_POST['scopes']??['read'];if(!is_array($scopes))$scopes=['read'];$allowed=['read','write','secrets'];$scopes=array_values(array_intersect($allowed,$scopes));$plain='acct_ws_'.rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$days=max(0,(int)($_POST['days']??365));$exp=$days?date('Y-m-d H:i:s',time()+$days*86400):null;pdo()->prepare("INSERT INTO workspace_api_tokens (workspace_id,user_id,name,token_hash,token_prefix,scopes,expires_at,created_at) VALUES (?,?,?,?,?,?,?,NOW())")->execute([Tenant::id(),(int)Auth::user()['id'],$name,hash('sha256',$plain),substr($plain,0,18),json_encode($scopes),$exp]);$_SESSION['new_api_token']=$plain;redirect('api_tokens.php');}if($a==='revoke'){pdo()->prepare("UPDATE workspace_api_tokens SET revoked_at=NOW() WHERE id=? AND workspace_id=?")->execute([(int)$_POST['id'],Tenant::id()]);redirect('api_tokens.php');}}
$st=pdo()->prepare("SELECT * FROM workspace_api_tokens WHERE workspace_id=? ORDER BY id DESC");$st->execute([Tenant::id()]);$rows=$st->fetchAll();$new=$_SESSION['new_api_token']??'';unset($_SESSION['new_api_token']);
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>API Tokens</title><link rel="stylesheet" href="assets/style.css?v=4.0"></head><body><main class="main" style="max-width:900px;margin:auto"><div class="topbar"><div><h1>API Tokenهای محیط کاری</h1><p><?=h(Tenant::current()['name']??'')?></p></div><a class="btn" href="index.php?page=settings">بازگشت</a></div><?php if($new):?><section class="card alert success"><b>این Token فقط همین یک بار نمایش داده می‌شود:</b><code class="code"><?=h($new)?></code></section><?php endif;?><section class="card"><form method="post" class="grid-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>نام<input name="name" required></label><label>اعتبار (روز)<input type="number" name="days" value="365"></label><label class="check"><input type="checkbox" name="scopes[]" value="read" checked> read</label><label class="check"><input type="checkbox" name="scopes[]" value="write"> write</label><label class="check"><input type="checkbox" name="scopes[]" value="secrets"> secrets</label><button class="btn primary">ساخت توکن</button></form></section><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>نام</th><th>Prefix</th><th>Scope</th><th>آخرین استفاده</th><th>انقضا</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td dir="ltr"><?=h($r['token_prefix'])?>...</td><td><?=h($r['scopes'])?></td><td><?=h($r['last_used_at'])?></td><td><?=h($r['expires_at'])?></td><td><?php if(!$r['revoked_at']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn tiny danger">لغو</button></form><?php else:?>لغوشده<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>